using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Splines;using Unity.Mathematics;using TutorialFramework;using Object=UnityEngine.Object;
[InitializeOnLoad]public static class WireVisibilityGeometry {
 [Serializable]public class Change{public string id,name;public bool runtime;public float sagDelta,depthDelta,lateralDelta;public Vector3[] points,tin,tout;}
 [Serializable]public class Changes{public Change[] wires;}
 static WireVisibilityGeometry(){EditorApplication.update+=Tick;}
 static void Tick(){const string f="Temp/wire-geometry.flag";if(!File.Exists(f)||EditorApplication.isCompiling||EditorApplication.isUpdating||Application.isPlaying)return;string action=File.ReadAllText(f).Trim();File.Delete(f);try{if(action=="apply")Apply();else Preview(action);}catch(Exception e){File.WriteAllText("Temp/WireVisibility/geometry-error.txt",e.ToString());}}
 static SplineContainer Find(string id){GlobalObjectId.TryParse(id,out var gid);return GlobalObjectId.GlobalObjectIdentifierToObjectSlow(gid) as SplineContainer;}
 static void Apply(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var changes=JsonUtility.FromJson<Changes>(File.ReadAllText("Temp/WireVisibility/apply.json"));foreach(var item in changes.wires){var c=Find(item.id);if(!c)throw new Exception("Missing spline "+item.name);if(item.runtime){var route=c.GetComponentInParent<FreeLabWire>(true);var so=new SerializedObject(route);so.FindProperty("fitToAllocatedPlugs").boolValue=false;so.ApplyModifiedPropertiesWithoutUndo();}
 {var knots=new List<BezierKnot>();for(int i=0;i<item.points.Length;i++)knots.Add(new BezierKnot((float3)c.transform.InverseTransformPoint(item.points[i]),(float3)c.transform.InverseTransformVector(item.tin[i]),(float3)c.transform.InverseTransformVector(item.tout[i]),quaternion.identity));var list=c.Splines.ToArray();list[0]=new Spline(knots,false);c.Splines=list;EditorUtility.SetDirty(c);foreach(var e in c.GetComponents<SplineExtrude>())e.Rebuild();}}
 EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("Temp/WireVisibility/applied.txt","Applied "+changes.wires.Length+" cable curve/configuration adjustments");}
 static void Preview(string phase){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var states=all.ToDictionary(t=>t.gameObject,t=>t.gameObject.activeSelf);var wires=all.Select(t=>t.GetComponent<WireInteraction>()).Where(w=>w&&w.wireObject).ToArray();var mover=all.Select(t=>t.GetComponent<SmoothCameraMovement>()).First(x=>x);var positions=new SerializedObject(mover).FindProperty("cameraPositions");var source=mover.GetComponent<Camera>();if(!source)source=all.Select(t=>t.GetComponent<Camera>()).First(c=>c);
 var go=new GameObject("Wire visibility preview camera"){hideFlags=HideFlags.HideAndDontSave};var cam=go.AddComponent<Camera>();cam.CopyFrom(source);cam.enabled=false;var rt=new RenderTexture(1600,900,24);rt.Create();cam.targetTexture=rt;
 try{foreach(var board in all.Select(t=>t.GetComponent<StoryboardSteps>()).Where(b=>b&&new[]{"Exp 1","Exp 2","Exp 3","Exp 4"}.Contains(b.name))){foreach(var pair in states)pair.Key.SetActive(pair.Value);foreach(var b in all.Select(t=>t.GetComponent<StoryboardSteps>()).Where(b=>b))b.gameObject.SetActive(false);foreach(var canvas in all.Select(t=>t.GetComponent<Canvas>()).Where(c=>c))canvas.gameObject.SetActive(false);foreach(var w in wires)w.wireObject.SetActive(false);
 foreach(var w in board.steps.Select(s=>s.interaction as WireInteraction).Where(w=>w&&w.wireObject)){foreach(var obj in new[]{w.wireObject,w.plugA,w.plugB}.Where(x=>x))for(var t=obj.transform;t;t=t.parent)t.gameObject.SetActive(true);foreach(var e in w.wireObject.GetComponentsInChildren<SplineExtrude>(true))e.Rebuild();}
 var indices=board.name=="Exp 1"?new[]{2,8}:board.name=="Exp 2"?new[]{3,8,9}:board.name=="Exp 3"?new[]{3,6,8,9}:new[]{3,4,5,8};
 foreach(int index in indices){var target=(Transform)positions.GetArrayElementAtIndex(index).objectReferenceValue;cam.transform.SetPositionAndRotation(target.position,target.rotation);cam.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(1600,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,900),0,0);tex.Apply();File.WriteAllBytes("Temp/WireVisibility/"+phase+"-"+board.name.Replace(" ","")+"-cam"+index+".png",tex.EncodeToPNG());Object.DestroyImmediate(tex);RenderTexture.active=previous;}}
 }finally{foreach(var pair in states)if(pair.Key)pair.Key.SetActive(pair.Value);cam.targetTexture=null;rt.Release();Object.DestroyImmediate(rt);Object.DestroyImmediate(go);}File.WriteAllText("Temp/WireVisibility/render-"+phase+".txt","Completed authored camera previews; all activity states restored");}
}
